<template>
  <div class="entry-detail">
    <el-breadcrumb separator="/" class="crumb"><el-breadcrumb-item :to="{ path: '/' }">首页</el-breadcrumb-item><el-breadcrumb-item :to="{ path: `/module/${entry?.moduleId}` }">{{ moduleName }}</el-breadcrumb-item><el-breadcrumb-item>{{ entry?.title }}</el-breadcrumb-item></el-breadcrumb>

    <div v-if="entry" class="readme-card vl-card">
      <header class="readme-header">
        <div class="header-main"><span class="type-pill" :style="{ background: typeColor + '1a', color: typeColor }">{{ typeLabel }}</span><h1>{{ entry.title }}</h1><div v-if="tagList.length" class="tag-row"><span v-for="tag in tagList" :key="tag" class="tag">#{{ tag }}</span></div></div>
        <div class="header-actions"><el-tooltip content="显示目录" placement="bottom"><el-button circle @click="catalogOpen = !catalogOpen">☷</el-button></el-tooltip><el-tooltip content="编辑笔记" placement="bottom"><button class="btn-ink edit-button" @click="goEdit">✎ <span>编辑</span></button></el-tooltip></div>
      </header>

      <div v-if="algorithmData && (algorithmData.leetcodeId || algorithmData.difficulty || algorithmData.complexity)" class="meta-box"><div v-if="algorithmData.leetcodeId" class="meta-item"><span>LeetCode</span><strong>#{{ algorithmData.leetcodeId }}</strong></div><div v-if="algorithmData.difficulty" class="meta-item"><span>难度</span><strong :class="algorithmData.difficulty">{{ difficultyLabel }}</strong></div><div v-if="algorithmData.complexity" class="meta-item"><span>时间复杂度</span><strong>{{ algorithmData.complexity }}</strong></div></div>

      <div class="study-row"><span>学习状态</span><el-radio-group :model-value="entry.status" @change="handleStatus"><el-radio-button :label="0">未做</el-radio-button><el-radio-button :label="1">在做</el-radio-button><el-radio-button :label="2">已掌握</el-radio-button></el-radio-group></div>

      <div class="readme-body" :class="{ 'catalog-open': catalogOpen }">
        <aside v-if="catalog.length" class="catalog"><div class="catalog-title">本篇目录</div><button v-for="item in catalog" :key="item.id" :class="`level-${item.level}`" @click="scrollToHeading(item.id)">{{ item.text }}</button></aside>
        <main ref="contentRef" class="md-content readme-content" @click="handleContentClick" v-html="renderedHtml"></main>
      </div>

      <section v-if="attachments.length" class="attachment-section"><div class="section-title">相关资料 <span>{{ attachments.length }}</span></div><div class="attachment-grid"><a v-for="file in attachments" :key="file.id" class="attachment-card" @click.prevent="downloadAttachment(file)"><span class="file-icon">{{ isImage(file.contentType) ? '▧' : '▤' }}</span><span class="file-info"><strong>{{ file.originalName }}</strong><small>{{ formatSize(file.fileSize) }} · {{ isImage(file.contentType) ? '图片' : '附件' }}</small></span><span class="download">↓</span></a></div></section>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import MarkdownIt from 'markdown-it'
import { ElMessage } from 'element-plus'
import { entryApi, fileApi, moduleApi } from '@/api'
import { downloadAttachment, hydrateProtectedImages } from '@/utils/fileUrl'
import type { AlgorithmData, Entry, FileMetadata } from '@/types'

interface Heading { id: string; text: string; level: number }
const route = useRoute(); const router = useRouter(); const entryId = Number(route.params.id)
const md = new MarkdownIt({ html: false, linkify: true, breaks: true }); const entry = ref<Entry | null>(null); const moduleName = ref(''); const attachments = ref<FileMetadata[]>([]); const catalogOpen = ref(true); const contentRef = ref<HTMLElement | null>(null)
const typeMap: Record<string, { label: string; color: string }> = { note: { label: '笔记', color: '#4f8cff' }, algorithm: { label: '算法', color: '#ea4c89' }, qa: { label: '八股', color: '#7c5cff' }, link: { label: '链接', color: '#0bb8b8' } }
const typeLabel = computed(() => entry.value ? typeMap[entry.value.type]?.label || '笔记' : ''); const typeColor = computed(() => entry.value ? typeMap[entry.value.type]?.color || '#6e6d7a' : '#6e6d7a'); const tagList = computed(() => entry.value?.tags ? entry.value.tags.split(',').map(tag => tag.trim()).filter(Boolean) : [])
const algorithmData = computed<AlgorithmData | null>(() => { if (!entry.value?.dataJson) return null; try { return JSON.parse(entry.value.dataJson) } catch { return null } }); const difficultyLabel = computed(() => { const difficulty = algorithmData.value?.difficulty; if (difficulty === 'easy') return '简单'; if (difficulty === 'medium') return '中等'; if (difficulty === 'hard') return '困难'; return difficulty })
const catalog = computed<Heading[]>(() => { const content = entry.value?.contentMd || ''; const headings: Heading[] = []; const lines = content.split('\n'); let codeFence = false; lines.forEach(line => { if (/^\s*```/.test(line)) { codeFence = !codeFence; return }; if (codeFence) return; const match = line.match(/^(#{1,3})\s+(.+?)\s*#*\s*$/); if (match) { const text = match[2].replace(/[*_`~\[\]]/g, '').trim(); headings.push({ id: `heading-${headings.length}`, text, level: match[1].length }) } }); return headings })
const renderedHtml = computed(() => { let index = 0; return md.render(entry.value?.contentMd || '*暂无内容，点击右上角编辑开始记录。*').replace(/<h([1-3])>(.*?)<\/h\1>/g, (_, level, content) => `<h${level} id="heading-${index++}">${content}</h${level}>`) })
const formatSize = (size: number) => size < 1024 * 1024 ? `${Math.max(1, Math.round(size / 1024))} KB` : `${(size / 1024 / 1024).toFixed(1)} MB`; const isImage = (type: string) => type.startsWith('image/')
const scrollToHeading = (id: string) => document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' })
const handleContentClick = async (event: MouseEvent) => { const target = event.target as HTMLElement; const button = target.closest<HTMLButtonElement>('[data-copy-code]'); if (!button) return; const code = button.parentElement?.querySelector('code')?.textContent || ''; try { await navigator.clipboard.writeText(code); button.textContent = '已复制'; window.setTimeout(() => { button.textContent = '复制代码' }, 1600) } catch { ElMessage.error('复制失败，请手动复制') } }
const injectCopyButtons = async () => { await nextTick(); contentRef.value?.querySelectorAll('pre').forEach(pre => { if (pre.querySelector('[data-copy-code]')) return; const button = document.createElement('button'); button.type = 'button'; button.dataset.copyCode = 'true'; button.textContent = '复制代码'; pre.appendChild(button) }); await hydrateProtectedImages(contentRef.value) }
const handleStatus = async (status: number) => { await entryApi.updateStatus(entryId, status); if (entry.value) entry.value.status = status as Entry['status']; ElMessage.success('状态已更新') }
const goEdit = () => router.push(`/entry/edit/${entry.value!.moduleId}/${entryId}`)
onMounted(async () => { const res = await entryApi.detail(entryId); entry.value = res.data; if (entry.value.moduleId) { const mRes = await moduleApi.detail(entry.value.moduleId); moduleName.value = mRes.data.name }; try { attachments.value = (await fileApi.list(entryId)).data || [] } catch { /* optional file service */ }; injectCopyButtons() })
watch(renderedHtml, injectCopyButtons)
</script>

<style scoped lang="scss">
.entry-detail { animation: page-fade 0.2s ease; }.crumb { margin-bottom: 20px; }.readme-card { overflow: hidden; }.readme-header { display: flex; justify-content: space-between; gap: 24px; padding: 29px 32px 25px; border-bottom: 1px solid $border-soft; }.header-main h1 { margin: 10px 0 13px; color: $ink; font-size: 30px; font-weight: 800; letter-spacing: -0.035em; }.type-pill { display: inline-flex; padding: 4px 11px; border-radius: $radius-pill; font-size: 12px; font-weight: 700; }.tag-row { display: flex; flex-wrap: wrap; gap: 7px; }.tag { padding: 3px 9px; background: $bg-subtle; border-radius: $radius-sm; color: $muted; font-size: 12px; }.header-actions { display: flex; align-items: flex-start; gap: 8px; flex-shrink: 0; }.edit-button { height: 36px; padding: 0 16px; }.meta-box { display: flex; flex-wrap: wrap; gap: 38px; margin: 22px 32px 0; padding: 15px 20px; background: $bg-subtle; border-radius: $radius-md; }.meta-item { display: flex; flex-direction: column; gap: 4px; }.meta-item span { color: $muted; font-size: 12px; }.meta-item strong { color: $ink; font-size: 14px; }.meta-item strong.easy { color: $success; }.meta-item strong.medium { color: $warning; }.meta-item strong.hard { color: $danger; }.study-row { display: flex; align-items: center; gap: 13px; padding: 20px 32px; color: $muted; font-size: 13px; }.readme-body { display: grid; grid-template-columns: 0 minmax(0, 1fr); border-top: 1px solid $border-soft; transition: grid-template-columns 0.2s ease; }.readme-body.catalog-open { grid-template-columns: 210px minmax(0, 1fr); }.catalog { position: sticky; top: calc(var(--vl-header-h) + 14px); align-self: start; max-height: calc(100vh - var(--vl-header-h) - 30px); overflow-y: auto; padding: 24px 14px 24px 24px; border-right: 1px solid $border-soft; }.catalog-title { margin-bottom: 12px; color: $ink; font-size: 13px; font-weight: 800; }.catalog button { display: block; width: 100%; padding: 7px 6px; overflow: hidden; border: 0; border-radius: 5px; background: transparent; color: $muted; cursor: pointer; font-size: 13px; text-align: left; text-overflow: ellipsis; white-space: nowrap; }.catalog button:hover { background: $bg-subtle; color: $ink; }.catalog .level-2 { padding-left: 16px; }.catalog .level-3 { padding-left: 28px; font-size: 12px; }.readme-content { min-width: 0; padding: 26px 42px 42px; }.readme-content :deep(h1), .readme-content :deep(h2), .readme-content :deep(h3) { scroll-margin-top: calc(var(--vl-header-h) + 22px); }.readme-content :deep(pre) { position: relative; }.readme-content :deep([data-copy-code]) { position: absolute; top: 9px; right: 9px; padding: 4px 8px; border: 1px solid rgba(255,255,255,0.2); border-radius: 5px; background: rgba(255,255,255,0.09); color: #e8e8ed; cursor: pointer; font-size: 11px; }.readme-content :deep([data-copy-code]:hover) { background: rgba(255,255,255,0.18); }.attachment-section { padding: 24px 32px 32px; border-top: 1px solid $border-soft; }.section-title { margin-bottom: 13px; color: $ink; font-size: 15px; font-weight: 800; }.section-title span { margin-left: 5px; color: $muted; font-size: 12px; }.attachment-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px; }.attachment-card { display: flex; align-items: center; gap: 10px; padding: 12px; border: 1px solid $border-soft; border-radius: $radius-sm; transition: border-color 0.15s ease, background 0.15s ease; }.attachment-card:hover { border-color: $primary; background: $bg-subtle; }.file-icon { color: $primary; font-size: 21px; }.file-info { display: flex; flex: 1; min-width: 0; flex-direction: column; gap: 3px; }.file-info strong { overflow: hidden; color: $ink-soft; font-size: 13px; text-overflow: ellipsis; white-space: nowrap; }.file-info small { color: $muted; font-size: 11px; }.download { color: $muted; font-size: 19px; }
@media (max-width: 768px) { .readme-header { padding: 20px 18px; }.header-main h1 { font-size: 23px; }.edit-button span { display: none; }.edit-button { width: 36px; padding: 0; justify-content: center; }.meta-box { gap: 18px 32px; margin: 16px 18px 0; padding: 13px 15px; }.study-row { flex-wrap: wrap; padding: 16px 18px; }.readme-body.catalog-open, .readme-body { display: block; }.catalog { position: static; max-height: 0; padding: 0; overflow: hidden; border-right: 0; transition: max-height 0.2s ease; }.catalog-open .catalog { max-height: 260px; padding: 16px 18px; border-bottom: 1px solid $border-soft; }.readme-content { padding: 20px 18px 30px; }.attachment-section { padding: 20px 18px 24px; } }
@keyframes page-fade { from { opacity: 0; } to { opacity: 1; } }
</style>
